import React, { useState } from 'react';
import {
  Button,
  Drawer,
  DrawerHeader,
  DrawerTitle,
  DrawerBody,
  DrawerCloseButton,
  Menu,
  MenuItem,
  MenuDivider,
} from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavDrawerMenuProps {
  onNavigate: (key: NavKey) => void;
}

const NavDrawerMenu: React.FC<NavDrawerMenuProps> = ({ onNavigate }) => {
  const [isOpen, setIsOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setIsOpen(false);
  };

  return (
    <>
      <Button variant="secondary" onClick={() => setIsOpen(true)}>
        Меню
      </Button>

      <Drawer
        placement="left"
        open={isOpen}
        onClose={() => setIsOpen(false)}
        className="jx-nav-drawer"
      >
        <DrawerHeader>
          <DrawerTitle>Навигация</DrawerTitle>
          <DrawerCloseButton onClick={() => setIsOpen(false)} />
        </DrawerHeader>
        <DrawerBody>
          <Menu>
            <MenuItem onSelect={() => handleSelect('projects')}>
              Проекты
            </MenuItem>
            <MenuItem onSelect={() => handleSelect('team')}>
              Команда
            </MenuItem>
            <MenuItem onSelect={() => handleSelect('settings')}>
              Настройки
            </MenuItem>
            <MenuDivider />
            <MenuItem
              variant="danger"
              onSelect={() => handleSelect('logout')}
            >
              Выйти
            </MenuItem>
          </Menu>
        </DrawerBody>
      </Drawer>
    </>
  );
};

export default NavDrawerMenu;

